package Lec_01;

public class max_3numbers {

	public static void main(String[] args) {
		// TODO Auto-generated method 
		int a=33;
		int b=55;
		int c=44;
		if((a>=b)&&(a>=c))
			System.out.println(a);
		else if((b>=a)&&(b>=c))
			System.out.println(b);
		else
			System.out.println(c);
	}

}
